server {
    listen 80;
    server_name myapp.com www.myapp.com;

    # Serve static files directly (fast)
    location /static/ {
        root /home/deploy/myapp/public;
        expires 1y;
        add_header Cache-Control "public, immutable";
    }

    # Proxy dynamic requests to Node.js
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';  # WebSocket support
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;

        # Timeouts
        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }
}

# After adding SSL with certbot:
# certbot --nginx -d myapp.com -d www.myapp.com
# Certbot modifies this file automatically to add SSL config

module.exports = {
  apps: [
    {
      name: 'myapp',
      script: 'dist/server.js',
      instances: 'max',          // use all CPU cores
      exec_mode: 'cluster',      // Node.js cluster mode
      autorestart: true,
      watch: false,              // don't watch files in production
      max_memory_restart: '500M',
      env: {
        NODE_ENV: 'production',
        PORT: 3000,
      },
      log_date_format: 'YYYY-MM-DD HH:mm:ss',
      error_file: '/home/deploy/logs/myapp-error.log',
      out_file: '/home/deploy/logs/myapp-out.log',
    },
  ],
};
